package com.saleshub.service;
import com.saleshub.domain.*; import com.saleshub.repository.*; import com.saleshub.web.SaleRequest; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*;
@Service public class SaleService { private final ProductRepository products; private final CustomerRepository customers; private final UserRepository users; private final SaleRepository sales; private final DiscountPolicy policy=new DiscountPolicy(); public SaleService(ProductRepository p,CustomerRepository c,UserRepository u,SaleRepository s){products=p;customers=c;users=u;sales=s;} @Transactional public Sale create(SaleRequest r){ User seller=users.findById(r.sellerId()).orElseThrow(()->new BusinessException("Vendedor inexistente")); Customer customer=r.customerId()==null?null:customers.findById(r.customerId()).orElseThrow(()->new BusinessException("Cliente inexistente")); if(r.items()==null||r.items().isEmpty())throw new BusinessException("Carrinho vazio"); BigDecimal subtotal=BigDecimal.ZERO; int qty=0; var loaded=new java.util.ArrayList<SaleItem>(); for(var line:r.items()){ Product p=products.findById(line.productId()).orElseThrow(()->new BusinessException("Produto inexistente: "+line.productId())); if(p.getStockQuantity()<line.quantity())throw new BusinessException("Estoque insuficiente: "+p.getName()); loaded.add(new SaleItem(p,line.quantity())); subtotal=subtotal.add(p.getPrice().multiply(BigDecimal.valueOf(line.quantity()))); qty+=line.quantity(); } BigDecimal discount=policy.calculate(subtotal,qty,customer,r.coupon()); Sale sale=new Sale(seller,customer,PaymentMethod.valueOf(r.paymentMethod()),subtotal,discount); for(var item:loaded){item.getProduct().decrease(item.getQuantity());sale.addItem(item);} return sales.save(sale); } @Transactional public void cancel(Long id){ Sale s=sales.findById(id).orElseThrow(()->new BusinessException("Venda inexistente")); if(s.getStatus()!=SaleStatus.COMPLETED)throw new BusinessException("Venda já encerrada"); s.getItems().forEach(i->i.getProduct().increase(i.getQuantity()));s.cancel(); } }
